#[derive(Clone)]
pub struct WitMcpCompatServer {
    tool_router: ToolRouter<Self>,
    prompt_router: PromptRouter<Self>,
}

impl WitMcpCompatServer {
    pub fn new() -> Self {
        Self {
            tool_router: Self::tool_router(),
            prompt_router: Self::prompt_router(),
        }
    }
}

impl Default for WitMcpCompatServer {
    fn default() -> Self {
        Self::new()
    }
}

pub async fn serve_stdio_compat() -> anyhow::Result<()> {
    ensure_rustls_provider();
    let service = WitMcpCompatServer::new()
        .serve(stdio())
        .await
        .inspect_err(|err| {
            tracing::error!(?err, "wit MCP server failed");
        })?;
    service.waiting().await?;
    Ok(())
}

