    pub async fn wit_sed(
        &self,
        Parameters(args): Parameters<SedArgs>,
    ) -> Result<Json<SedResponse>, String> {
        let max_bytes = validate_text_limit(args.max_bytes)?;
        let scripts = collect_sed_scripts(&args)?;
        let repo = cache_github_repo(
