+fn paginate_vec<T, F>(
+    tool: &str,
+    snapshot_id: Option<&str>,
+    fingerprint: &str,
+    cursor: Option<&str>,
+    items: Vec<T>,
+    max_items: usize,
+    max_bytes: usize,
+    include_rendered_text: bool,
+    render: F,
+) -> Result<Page<T>, String>
+where
+    T: Clone + Serialize,
+    F: Fn(&[T]) -> String,
+{
+    let offset = cursor_offset(tool, snapshot_id, fingerprint, cursor)?;
+    paginate_vec_with_offset(
+        tool,
+        snapshot_id,
+        fingerprint,
+        offset,
+        items,
+        max_items,
+        max_bytes,
+        include_rendered_text,
+        render,
+    )
+}
+
+fn paginate_vec_with_offset<T, F>(
+    tool: &str,
+    snapshot_id: Option<&str>,
+    fingerprint: &str,
+    offset: usize,
+    items: Vec<T>,
+    max_items: usize,
+    max_bytes: usize,
+    include_rendered_text: bool,
+    render: F,
+) -> Result<Page<T>, String>
+where
+    T: Clone + Serialize,
+    F: Fn(&[T]) -> String,
+{
+    let window = items
+        .into_iter()
+        .skip(offset)
+        .take(max_items + 1)
+        .collect();
+    paginate_window(
+        tool,
+        snapshot_id,
+        fingerprint,
+        offset,
+        window,
+        max_items,
+        max_bytes,
+        include_rendered_text,
+        render,
+    )
