+fn paginate_window<T, F>(
+    tool: &str,
+    snapshot_id: Option<&str>,
+    fingerprint: &str,
+    offset: usize,
+    mut window: Vec<T>,
+    max_items: usize,
+    max_bytes: usize,
+    include_rendered_text: bool,
+    render: F,
+) -> Result<Page<T>, String>
+where
+    T: Clone + Serialize,
+    F: Fn(&[T]) -> String,
+{
+    let had_more_by_count = window.len() > max_items;
+    window.truncate(max_items);
+    loop {
+        let has_more = had_more_by_count || window.len() < max_items;
+        let next_cursor = if has_more && !window.is_empty() {
