+                    .contains(&query.to_ascii_lowercase())
+            })
+            .count() as i64;
+        let position_bonus = 20_i64.saturating_sub((item.start_line / 100) as i64);
+        item.score = exact_hits * 100 + path_hits * 25 + hit_count * 10 + position_bonus;
+        if exact_hits > 0 {
